WITH p AS (SELECT %s::date d1,%s::date d2,coalesce(%s::text,'') search_key,%s::integer uid,%s::integer lim), s AS (SELECT p.*,u.user_id ok,coalesce(u.ds_branchs,'') bs,coalesce(u.is_super,0)=1 OR coalesce(u.ds_branchs,'')='' all_branch FROM p LEFT JOIN public.userinfo u ON u.user_id=p.uid) SELECT a.id_oi,a.id_change_cavity,a.ma_khuon,a.ma_sp,a.ln,a.id_cap,a.chu_ky,a.chinh_phu,a.cavity,a.tong_cavity,a.ten_sp,a.stt,a.cavity_goc,a.date0,a.time0,count(*) OVER() total FROM public.mes_oi_change_cativity a CROSS JOIN s WHERE s.ok IS NOT NULL AND a.date0 BETWEEN s.d1 AND s.d2 AND (s.search_key='' OR a.id_oi ILIKE '%%'||s.search_key||'%%' OR a.ma_sp=ANY(string_to_array(s.search_key,',')) OR a.ma_khuon=ANY(string_to_array(s.search_key,','))) AND (s.all_branch OR EXISTS(SELECT 1 FROM public.mes_oi_confirm c WHERE c.id_oi=a.id_oi AND c.branch_code=ANY(string_to_array(s.bs,',')))) ORDER BY a.date0 DESC,a.time0 DESC,a.id_change_cavity LIMIT (SELECT lim FROM p);
